sys_script_include.script:
var BOA_SI_USEM_RemediationTaskPayloadBuilder = Class.create();
BOA_SI_USEM_RemediationTaskPayloadBuilder.prototype = {

    /**
     * Configuration: envelope constants, date formats, the prefix of the field mapping property per
     * table, the exception approval states counted, the change request state left out (Canceled), the
     * two keys the payload derives itself, the journal field types, the display markup the platform
     * wraps around some calculated values, and the change request association table per remediation
     * task table.
     * @returns {void}
     */
    initialize: function() {
        this.TOPIC_NAME = 'sn_usem_remtask_outbound';
        this.NAMESPACE = 'com.bofa.usem';
        this.CORE_VERSION = '1.0.0';
        this.OUTBOUND_VERSION = '1.0.0';
        this.DATE_FORMAT = 'MM-dd-yyyy';
        this.TIME_FORMAT = 'HH:mm:ss';
        this.FIELDS_PROPERTY_PREFIX = 'x_boar_bofa_usem_1.usem.cdp.remtask.fields.';
        this.EXCEPTION_TABLE = 'sn_sec_exception_change_approval';
        this.EXCEPTION_STATES = '1,4';
        this.CHANGE_CANCELED = '4';
        this.DERIVED_KEYS = ['change_requests', 'exception_requests'];
        this.JOURNAL_TYPES = ['journal_input', 'journal', 'journal_list'];
        this.MARKUP = /^\[code\]([\s\S]*)\[\/code\]$/;
        this.CHANGE_LINKS = {
            sn_vul_vulnerability: {
                table: 'sn_vul_m2m_vg_change_request',
                field: 'sn_vul_vulnerability'
            },
            sn_vul_app_vulnerability: {
                table: 'sn_vul_app_m2m_vg_change_request',
                field: 'sn_vul_app_vulnerability'
            },
            sn_vul_container_vulnerability: {
                table: 'sn_vul_container_m2m_remediation_task_change_request',
                field: 'sn_vul_container_vulnerability'
            },
            sn_vulc_result_group: {
                table: 'sn_vulc_m2m_trg_change_request',
                field: 'result_group'
            }
        };
    },

    /**
     * Builds the outbound Kafka payload (envelope plus one remediation task) for a record. Fields
     * come from the property x_boar_bofa_usem_1.usem.cdp.remtask.fields.<table>, one
     * servicenow_field=json_field pair per line, a field missing on the table or empty being sent as
     * ""; on failure logs once and returns "".
     * @param {GlideRecord} record - the remediation task record
     * @param {String} normalizedOperation - the operation to report in the envelope, if known
     * @returns {Object} the payload object, or "" when it cannot be built
     */
    buildPayload: function(record, normalizedOperation) {
        try {
            if (!this._isRecord(record))
                throw new Error('record is not a valid GlideRecord');
            var payload = {
                envelope: this._buildEnvelope(this._activity(record, normalizedOperation)),
                rem_tasks: [{
                    remediation_task: this._buildRemediationTask(record)
                }]
            };
            return payload;
        } catch (e) {
            gs.error(this._errorMessage(record, e));
            return '';
        }
    },

    /**
     * Tells whether the value is a GlideRecord positioned on an existing record. getRefRecord() of a
     * document id whose table field is empty gives null, or in a scoped script an empty object
     * without the record methods; neither passes.
     * @param {*} record - the value to check
     * @returns {Boolean} true for a valid GlideRecord
     */
    _isRecord: function(record) {
        return record !== null && typeof record === 'object' && typeof record.isValidRecord === 'function' && record.isValidRecord();
    },

    /**
     * Formats the single error line: <class>: payload not built for <table> <sys_id> - <reason>.
     * @param {GlideRecord} record - the record being processed, if any
     * @param {Error} e - the error caught
     * @returns {String} the message to log
     */
    _errorMessage: function(record, e) {
        var subject = this._isRecord(record) ? ' for ' + record.getTableName() + ' ' + record.getUniqueValue() : '';
        return this.type + ': payload not built' + subject + ' - ' + e.message;
    },

    /**
     * Resolves the envelope activity: the given operation, otherwise the operation in progress in a
     * business rule, otherwise INSERT for a record never updated and UPDATE for any other.
     * @param {GlideRecord} record - the remediation task record
     * @param {String} normalizedOperation - the operation to report, if known
     * @returns {String} the operation in upper case
     */
    _activity: function(record, normalizedOperation) {
        var operation = String(normalizedOperation || record.operation() || '').toUpperCase();
        if (operation)
            return operation;
        return parseInt(record.getValue('sys_mod_count')) > 0 ? 'UPDATE' : 'INSERT';
    },

    /**
     * Builds the message envelope: topic, namespace, versions, a new event id, the UTC timestamp,
     * the element count and the activity.
     * @param {String} activity - the operation reported, e.g. INSERT or UPDATE
     * @returns {Object} the envelope
     */
    _buildEnvelope: function(activity) {
        return {
            type: 'record',
            topic_name: this.TOPIC_NAME,
            namespace: this.NAMESPACE,
            core_version: this.CORE_VERSION,
            outbound_version: this.OUTBOUND_VERSION,
            event_id: this._newEventId(),
            event_timestamp: this._utcTimestamp(),
            element_count: 1,
            element_activity: activity
        };
    },

    /**
     * Renders the mapped fields of the record in property order, then adds the derived
     * change_requests and exception_requests. Field types are read from a record of the table the
     * builder opens itself: a scoped application may not read the dictionary descriptor of a record
     * handed over by a global script.
     * @param {GlideRecord} record - the remediation task record
     * @returns {Object} json_field to value, every value a string
     */
    _buildRemediationTask: function(record) {
        var table = record.getTableName();
        var mapping = this._fieldMapping(table);
        var dictionary = new GlideRecord(table);
        var task = {};
        for (var i = 0; i < mapping.length; i++)
            task[mapping[i].json] = this._fieldValue(record, dictionary, mapping[i].field);
        task.change_requests = this._changeRequests(record, this.CHANGE_LINKS[table]);
        task.exception_requests = this._exceptionRequests(record);
        return task;
    },

    /**
     * Reads the table's field mapping property: one servicenow_field=json_field pair per line, a bare
     * field name keeping its own name.
     * @param {String} table - the remediation task table name
     * @returns {Array} [{field, json}] in property order
     * @throws {Error} when the table has no property, or the property holds no field, a line with more
     *                 than one "=", a line without a field name, a line with "=" but no payload name,
     *                 the same payload name twice, or a payload name the payload derives itself
     */
    _fieldMapping: function(table) {
        var property = this.FIELDS_PROPERTY_PREFIX + table;
        var value = gs.getProperty(property, '');
        if (!value)
            throw new Error('table ' + table + ' is not configured in property ' + property);
        var mapping = [], names = {};
        var entries = value.split(/\r?\n|,/);
        for (var i = 0; i < entries.length; i++) {
            var line = entries[i].trim();
            if (!line)
                continue;
            var pair = line.split('=');
            if (pair.length > 2)
                throw new Error('property ' + property + ' holds a line with more than one "=": "' + line + '"');
            var field = pair[0].trim();
            if (!field)
                throw new Error('property ' + property + ' holds a line without a field name: "' + line + '"');
            if (pair.length == 2 && !pair[1].trim())
                throw new Error('property ' + property + ' holds a line without a payload name: "' + line + '"');
            var json = pair.length == 2 ? pair[1].trim() : field;
            if (names[json])
                throw new Error('property ' + property + ' names ' + json + ' twice');
            if (this.DERIVED_KEYS.indexOf(json) >= 0)
                throw new Error('property ' + property + ' names ' + json + ', which the payload derives itself');
            names[json] = true;
            mapping.push({ field: field, json: json });
        }
        if (!mapping.length)
            throw new Error('property ' + property + ' holds no field');
        return mapping;
    },

    /**
     * Reads one field of the record as the string to send; "" when the field does not exist on the
     * table or is empty. A journal field is read from its latest entry.
     * @param {GlideRecord} record - the remediation task record
     * @param {GlideRecord} dictionary - a record of the same table, opened by the builder, whose
     *                                   field descriptors give the field types
     * @param {String} field - the field name
     * @returns {String} the rendered value
     */
    _fieldValue: function(record, dictionary, field) {
        if (!record.isValidField(field))
            return '';
        var element = record.getElement(field);
        if (element === null)
            return '';
        var descriptor = dictionary.getElement(field).getED();
        if (this.JOURNAL_TYPES.indexOf(String(descriptor.getInternalType())) >= 0)
            return this._latestEntry(element);
        if (element.nil())
            return '';
        return this._renderElement(element, descriptor);
    },

    /**
     * The text of the latest entry of a journal field, without the header line the platform adds
     * (date and time in the saving user's zone, and the author). A journal keeps its entries apart
     * from the record, so the field itself is empty on every save that adds no entry.
     * @param {GlideElement} element - the journal field
     * @returns {String} the latest entry's text, "" when the journal has none
     */
    _latestEntry: function(element) {
        var entry = String(element.getJournalEntry(1) || '');
        var header = entry.indexOf('\n');
        return header < 0 ? '' : entry.substring(header + 1).trim();
    },

    /**
     * Renders one populated field by its dictionary type: dates formatted; a reference as its display
     * value, "" when the record it points at is gone; a document id as the display value of its
     * record; an integer with choices as its label and a plain count as its stored number (a display
     * value would carry the user's thousands separator); strings, lists, booleans, durations, domains
     * and classes as their display value; everything else as stored. Display markup of the form
     * [code]...[/code] is sent as its visible text, never as HTML.
     * @param {GlideElement} element - the field element
     * @param {GlideElementDescriptor} descriptor - the field's dictionary descriptor
     * @returns {String} the rendered value
     */
    _renderElement: function(element, descriptor) {
        switch (String(descriptor.getInternalType())) {
            case 'glide_date_time':
            case 'due_date':
                return this._formatDateTime(element.getValue());
            case 'glide_date':
                return this._formatDate(element.getValue());
            case 'reference':
                return this._referenceDisplay(element);
            case 'document_id':
                var target = element.getRefRecord();
                return this._isRecord(target) ? String(target.getDisplayValue()) : '';
            case 'integer':
                return descriptor.isChoiceTable() ? String(element.getDisplayValue()) : String(element.getValue());
            case 'string':
            case 'glide_list':
            case 'boolean':
            case 'glide_duration':
            case 'timer':
            case 'domain_id':
            case 'sys_class_name':
            case 'choice':
                return this._plainText(String(element.getDisplayValue()));
            default:
                return this._plainText(String(element.getValue()));
        }
    },

    /**
     * The display value of a reference, "" when the record it points at no longer exists (some
     * releases then show the stored sys_id instead of a name).
     * @param {GlideElement} element - the reference field
     * @returns {String} the display value, or ""
     */
    _referenceDisplay: function(element) {
        var shown = String(element.getDisplayValue());
        return shown == String(element.getValue()) ? '' : shown;
    },

    /**
     * Turns display markup ([code]<a href=...>3</a>[/code]) into its visible text; any other value
     * is returned unchanged.
     * @param {String} value - the value as the platform gives it
     * @returns {String} the value without markup
     */
    _plainText: function(value) {
        var markup = this.MARKUP.exec(value);
        if (!markup)
            return value;
        return markup[1].replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').trim();
    },

    /**
     * Formats a stored date/time as MM-dd-yyyy HH:mm:ss.
     * @param {String} value - the stored date/time value
     * @returns {String} the formatted date and time
     */
    _formatDateTime: function(value) {
        var gdt = new GlideDateTime(value);
        return gdt.getDate().getByFormat(this.DATE_FORMAT) + ' ' + gdt.getTime().getByFormat(this.TIME_FORMAT);
    },

    /**
     * Formats a stored date as MM-dd-yyyy.
     * @param {String} value - the stored date value
     * @returns {String} the formatted date
     */
    _formatDate: function(value) {
        var gd = new GlideDate();
        gd.setValue(value);
        return gd.getByFormat(this.DATE_FORMAT);
    },

    /**
     * Collects the numbers of the change requests associated with the record through its table's
     * association table, in number order: each change once however many links point at it, a link
     * whose change no longer exists left out, and cancelled change requests left out.
     * @param {GlideRecord} record - the remediation task record
     * @param {Object} link - {table, field} of the association table, undefined when the table has none
     * @returns {String} comma-separated change request numbers, "" when none
     */
    _changeRequests: function(record, link) {
        if (!link)
            return '';
        var numbers = [], seen = {};
        var m2m = new GlideRecord(link.table);
        m2m.addQuery(link.field, record.getUniqueValue());
        m2m.addQuery('change_request.state', '!=', this.CHANGE_CANCELED);
        m2m.addNotNullQuery('change_request');
        m2m.orderBy('change_request.number');
        m2m.query();
        while (m2m.next()) {
            var id = String(m2m.getValue('change_request'));
            if (seen[id])
                continue;
            seen[id] = true;
            var change = m2m.getElement('change_request').getRefRecord();
            if (!this._isRecord(change))
                continue;
            numbers.push(String(change.getValue('number')));
        }
        return numbers.join(',');
    },

    /**
     * Collects the numbers of the approved or expired exception approvals raised for the record.
     * @param {GlideRecord} record - the remediation task record
     * @returns {String} comma-separated exception numbers, "" when none
     */
    _exceptionRequests: function(record) {
        var numbers = [];
        var exception = new GlideRecord(this.EXCEPTION_TABLE);
        exception.addQuery('table', record.getTableName());
        exception.addQuery('record', record.getUniqueValue());
        exception.addQuery('approval_state', 'IN', this.EXCEPTION_STATES);
        exception.orderBy('number');
        exception.query();
        while (exception.next())
            numbers.push(exception.getValue('number'));
        return numbers.join(',');
    },

    /**
     * Generates the envelope event id.
     * @returns {String} a new id in UUID form (8-4-4-4-12)
     */
    _newEventId: function() {
        var guid = gs.generateGUID();
        return guid.substring(0, 8) + '-' + guid.substring(8, 12) + '-' + guid.substring(12, 16) + '-' +
            guid.substring(16, 20) + '-' + guid.substring(20, 32);
    },

    /**
     * Gives the current time for the envelope.
     * @returns {String} UTC time as yyyy-MM-ddTHH:mm:ssZ
     */
    _utcTimestamp: function() {
        return new GlideDateTime().getValue().replace(' ', 'T') + 'Z';
    },

    type: 'BOA_SI_USEM_RemediationTaskPayloadBuilder'
};
